import{_ as n,o as r,c as t,ag as s}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"🔬 科学日报 | 2026年9月27日 · 深度扩展","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/science-daily/2026-09-27.md","filePath":"science-log/src/science-daily/2026-09-27.md"}'),e={name:"science-log/src/science-daily/2026-09-27.md"};function g(a,o,i,c,d,p){return r(),t("div",null,[...o[0]||(o[0]=[s('<h1 id="🔬-科学日报-2026年9月27日-·-深度扩展" tabindex="-1">🔬 科学日报 | 2026年9月27日 · 深度扩展 <a class="header-anchor" href="#🔬-科学日报-2026年9月27日-·-深度扩展" aria-label="Permalink to &quot;🔬 科学日报 | 2026年9月27日 · 深度扩展&quot;">​</a></h1><blockquote><p>来源：重建版简讯（2026-09-27 · 事后重建，共 10 条：科学前沿 5 + AI 前沿 5） 分析日期：2026-09-27 版本：扩展版（10 条深度 + 交叉关联） ⚠️ 本日简讯为<strong>事后重建版</strong>（2026-11-05 按 arXiv/CrossRef 日期回溯生成，非当日发布原文，不代表历史原貌）；当日为<strong>周日</strong>，Nature/Science/PNAS 该日 CrossRef 命中 0 条，科学 5 篇取自最近的刊出日 2026-09-25（Science Advances / PNAS）。</p></blockquote><hr><h2 id="🔬-一、科学前沿" tabindex="-1">🔬 一、科学前沿 <a class="header-anchor" href="#🔬-一、科学前沿" aria-label="Permalink to &quot;🔬 一、科学前沿&quot;">​</a></h2><h3 id="_1-地核形成即可解释地幔的强亲铁元素过剩-无需「晚期薄层」" tabindex="-1">1. 地核形成即可解释地幔的强亲铁元素过剩，无需「晚期薄层」 <a class="header-anchor" href="#_1-地核形成即可解释地幔的强亲铁元素过剩-无需「晚期薄层」" aria-label="Permalink to &quot;1. 地核形成即可解释地幔的强亲铁元素过剩，无需「晚期薄层」&quot;">​</a></h3><p><strong>原文</strong>：强亲铁元素（HSE）对金属有高亲和性，理论上应在地核形成时被大量带入地核、在地幔中极度亏损，但实测地幔丰度远高于低压低温分配实验的预测，且各 HSE 呈球粒陨石式的相对比例。作者用激光加热金刚石压腔在对应早期地球岩浆洋的温压条件下测定五种 HSE 的金属—硅酸盐分配系数，发现分配系数随温度显著下降；多阶段吸积模型据此可复现地幔的 HSE 丰度与比值，无需引入晚期薄层。</p><p><strong>深度扩展</strong>：</p><p>这项发表于《Science Advances》（2026-09-25）的工作由 Blanchard I、Siebert J、Calvo L、Lobanov SS、Guyot F、Petitgirard S 等完成，直击行星科学一个长达数十年的悖论。<strong>强亲铁元素（highly siderophile elements, HSE）</strong>——铼（Re）、锇（Os）、铱（Ir）、钯（Pd）、金（Au）等——在金属/硅酸盐之间的分配系数极大，理应在地核与地幔分离（core formation）时被金属相几乎全部「刮走」，地幔应极度亏损。可是实测地幔的 HSE 丰度比低压低温实验外推值高出好几个数量级，而且各 HSE 之间呈<strong>球粒陨石式的相对比例</strong>——这两点长期只能靠「晚期薄层（late veneer）」假说解释：地核形成之后，再有一批球粒陨石（约地幔质量 0.5%）落进来把 HSE 补上，同时带来部分挥发分。</p><p><strong>方法</strong>：作者用<strong>激光加热金刚石压腔（LH-DAC）</strong>，在直接对应早期地球岩浆洋的高温高压条件下，实测这五种 HSE 的金属—硅酸盐分配系数。关键结果是：<strong>分配系数随温度显著下降</strong>——高温下 HSE 留在硅酸盐熔体里的倾向大增，远不像低温实验显示的那样「见金属就被抽干」。</p><p><strong>为什么重要</strong>：把这个温度依赖代进<strong>多阶段吸积模型</strong>，能同时复现地幔的 HSE 丰度与它们之间的比例，<strong>不再需要晚期薄层</strong>。这有两重后果：其一，百年悖论被一条更简约的路径消解（奥卡姆剃刀）；其二，「年轻地球的挥发分（水、碳、氮）从何而来」也随之改判——主要由<strong>早期吸积与分异</strong>过程带到地球，而非依赖一次晚到的球粒陨石投递。对理解类地行星的水源与宜居性起点，这是一个范式级的调整。</p><p><strong>跨主题关联</strong>：与 <code>topics/earth-science/index.md</code> 的地核—地幔分异与行星吸积主题直接同源；「高温改变分配行为」与 <code>topics/materials/index.md</code> 里高压/高温相变决定材料命运的思路互参；方法论上（LH-DAC 极端条件实验）与 <code>topics/physics/index.md</code> 的高压物理线一脉相承。</p><hr><h3 id="_2-电子叠层成像在原子尺度定量金属氢化物中的氢" tabindex="-1">2. 电子叠层成像在原子尺度定量金属氢化物中的氢 <a class="header-anchor" href="#_2-电子叠层成像在原子尺度定量金属氢化物中的氢" aria-label="Permalink to &quot;2. 电子叠层成像在原子尺度定量金属氢化物中的氢&quot;">​</a></h3><p><strong>原文</strong>：氢是最轻的元素，电子散射极弱、迁移性高，常规透射电镜难以定位其原子占位。作者以能量过滤多层电子叠层成像（MEP）对复杂高熵合金氢化物成像，分辨出皮米级氢位移与显著的三维不均匀性，并发现氢的引入意外抑制了原始高熵合金中固有的晶格畸变。</p><p><strong>深度扩展</strong>：</p><p>这项发表于《Science Advances》（2026-09-25）的工作由 Li P、Pua C、Dong Z、Cai C、Shen H、Gu L、Chen Z 等（含中科院金属所/高校团队）完成，解决的是一个「看着简单、做起来极难」的问题：<strong>如何在原子尺度看见并定量氢</strong>。氢是最轻、电子散射最弱的元素，且迁移性极高，常规透射电镜（TEM）既缺乏散射对比、又难以在电子束下固定它，因此氢在复杂材料中的<strong>原子占位与空间分布长期「不可见」</strong>——而这恰恰是理解氢脆、储氢、以及氢致电子相变的关键。</p><p><strong>方法</strong>：作者用<strong>能量过滤多层电子叠层成像（energy-filtered multislice electron ptychography, MEP）</strong>。叠层成像（ptychography）通过扫描时重叠衍射图样的相位反演，把电子探针的相位信息「算」出来，能突破常规成像的对比与分辨率限制；能量过滤则剔除非弹性散射造成的背景。把它用于一种<strong>复杂高熵合金（HEA）氢化物</strong>，作者分辨出了此前无法获取的结构细节：<strong>皮米（pm）级的氢位移</strong>与显著的<strong>三维不均匀性</strong>。</p><p><strong>为什么重要（关键数字与反直觉）</strong>：统计分析给出一个反直觉结论——<strong>氢的引入意外抑制了原始高熵合金中固有的晶格畸变</strong>。通常认为溶入小原子的氢会加剧局部应变；这里却相反，氢似乎在「抚平」高熵合金本就存在的晶格畸变。这为「氢如何改变金属结构与力学/电子性质」提供了直接的原子级证据链，也把 MEP 确立为<strong>原子级定量氢成像平台</strong>，可迁移到氢脆机制、固态储氢材料与氢致相变的研究中。</p><p><strong>跨主题关联</strong>：与 <code>topics/materials/index.md</code> 的合金/储氢材料主题直接同源，是「看清楚才能设计好」的表征驱动范式；与 <code>topics/physics/index.md</code> 的电子显微与衍射方法线互参；「氢在固体中的行为」与 2026-09-28 日报（重建版）中「天然氢藏作地下储氢场址」虽分处原子与地质两尺度，却同属「氢与固体的相互作用/存储」这一族问题，可对照阅读。</p><hr><h3 id="_3-合成-fls2-受体二聚体提升植物先天免疫" tabindex="-1">3. 合成 FLS2 受体二聚体提升植物先天免疫 <a class="header-anchor" href="#_3-合成-fls2-受体二聚体提升植物先天免疫" aria-label="Permalink to &quot;3. 合成 FLS2 受体二聚体提升植物先天免疫&quot;">​</a></h3><p><strong>原文</strong>：细胞表面受体的逐步组装与寡聚化是免疫激活与周转的关键，但植物免疫中「动态、时空受控的组装如何带来快速且持久的信号」一直不清楚。作者用合成工程手段精确控制拟南芥 FLS2 受体的寡聚状态，发现 FLS2 从以单体为主的静息态、在激活时转为瞬时的同源二聚；人工构造的同源二聚显著增强防御反应，同时避开会阻碍受体动态补充、损害持久免疫的高阶组装。</p><p><strong>深度扩展</strong>：</p><p>这项发表于《Science Advances》（2026-09-25）的工作由 Ma Z、Xie Y、Zhu X、Chng CP、Liang Q、Huang C、Miao Y 等完成，把「受体如何组装」这一细胞生物学问题，转成一个可被工程控制的<strong>合成生物学</strong>问题。背景是：细胞表面受体（如免疫受体）的<strong>逐步组装与寡聚化</strong>决定免疫激活的强度与持续时间；但在植物先天免疫里，受体的动态、时空受控组装如何同时实现「快」与「久」，因动态互作的复杂度而难以厘清。拟南芥的 <strong>FLS2</strong> 是识别细菌鞭毛蛋白（flg22）的经典模式识别受体，其激活依赖与共受体 BAK1 的异源二聚化，但 FLS2 自身的寡聚态变化此前不明确。</p><p><strong>方法</strong>：作者用<strong>合成工程</strong>手段，精确控制 FLS2 的寡聚状态（强制单体、强制二聚、强制高阶多聚），再配合<strong>单颗粒成像与定量标定</strong>，逐步读出各状态下受体的行为。结果给出一个清晰的「最优寡聚度」：FLS2 在静息态主要以<strong>单体</strong>存在，激活时短暂转为<strong>同源二聚</strong>；而人工强制的<strong>同源二聚</strong>能显著增强植物防御反应。</p><p><strong>为什么重要（关键洞见）</strong>：真正精巧之处在于「<strong>避开高阶组装</strong>」。强制形成高阶（多聚）受体会<strong>阻碍受体的动态补充</strong>——新受体无法轮换上阵，于是信号虽一时强、却无法持久，长效免疫反而受损。也就是说，免疫信号的「即时激活」与「长期维持」由<strong>不同的寡聚态</strong>分别优化：二聚利于即时放大，而可控的低阶组装才允许持续周转。这为「工程化耐久植物免疫」提供了可操作的分子旋钮：与其一味增强受体激活，不如<strong>精确控制组装层级</strong>，让受体既能被点燃、又能被反复补充。</p><p><strong>跨主题关联</strong>：与 <code>topics/biomedicine/index.md</code> 的受体信号/免疫识别主题同源；「精确控制组装层级以兼顾即时与持久」与 <code>topics/cross-domain-synthesis-2026-q3.md</code> 的「约束-涌现」模式可互参——组装的<strong>层级约束</strong>决定了系统能维持多久；工程化思路与 <code>topics/materials/index.md</code>（合成生物学材料/分子工程）线一脉相承。</p><hr><h3 id="_4-丘脑—前额叶突触减弱是青春期-nmdar-功能低下致短时记忆缺损的机制" tabindex="-1">4. 丘脑—前额叶突触减弱是青春期 NMDAR 功能低下致短时记忆缺损的机制 <a class="header-anchor" href="#_4-丘脑—前额叶突触减弱是青春期-nmdar-功能低下致短时记忆缺损的机制" aria-label="Permalink to &quot;4. 丘脑—前额叶突触减弱是青春期 NMDAR 功能低下致短时记忆缺损的机制&quot;">​</a></h3><p><strong>原文</strong>：丘脑—前额叶（TF）连接受损是精神分裂症最一致的环路异常之一，并与短时记忆（STM）缺损相关，但其生物学机制不明。作者发现青春期反复 NMDAR 拮抗（氯胺酮）使小鼠 STM 缺损伴随内侧背侧丘脑→背内侧前额叶突触的释放概率下降与短时程抑制减弱；用化学遗传学增强该投射可同时恢复神经选择性与行为。</p><p><strong>深度扩展</strong>：</p><p>这项发表于《Science Advances》（2026-09-25）的工作由 Yu Jinseon、Choi In Sun、Kim Gyu Hyun、Bahn Sangkyu、Choi Joon Ho、Rah Jong-Cheol 等（韩国团队）完成，聚焦精神分裂症的一个核心环路异常：<strong>丘脑—前额叶（thalamofrontal, TF）失连接</strong>。临床与影像研究反复发现 TF 连接减弱与**短时记忆（short-term memory, STM）**缺损相关，但「连接为什么变弱」的生物学机制一直空白。已知 **NMDAR 功能低下（hypofunction）**是精神分裂症的主流假说之一，青春期又是相关环路成熟的关键窗口。</p><p><strong>方法</strong>：作者让小鼠在<strong>青春期反复暴露于 NMDAR 拮抗剂氯胺酮</strong>，复现出 STM 缺损，再逐层追查突触与环路。关键定位是一个<strong>投射特异性的突触前机制</strong>：<strong>内侧背侧丘脑（MD）→背内侧前额叶（dmPFC）<strong>突触上，神经递质</strong>释放概率下降</strong>、<strong>短时程抑制（short-term depression）减弱</strong>；而同一实验中，皮质—皮质（corticocortical）突触的释放概率、神经元内在兴奋性、以及大体突触超微结构<strong>均无显著变化</strong>——即损伤精准落在 MD→dmPFC 这一条投射上。功能层面，dmPFC 的<strong>方向选择性群体编码</strong>减弱，延迟交替（delayed alternation）作业表现受损。</p><p><strong>为什么重要（因果闭环）</strong>：作者进一步用<strong>化学遗传学增强 MD→dmPFC 投射</strong>，结果<strong>同时恢复了神经选择性与行为</strong>——这把「突触前释放缺陷 → 群体编码退化 → 认知缺损」连成了一条可干预的因果链，而不仅仅是一个相关性。其意义在于：精神分裂症的 NMDAR 假说长期缺少「环路级、投射级」的落点，这里指出问题不在广泛皮层、而在一条<strong>特定丘脑—前额叶投射的突触前释放</strong>——为「投射靶向」的干预提供了明确的解剖坐标。</p><p><strong>跨主题关联</strong>：与 <code>topics/neuroscience/index.md</code> 的突触/环路与精神疾病主题直接同源；「释放概率—短时程可塑性决定工作记忆编码」与库内多篇日报（如 2026-07-06 的神经细胞死亡机制、2026-10-19 的听觉皮层 L5 树突编码）构成「认知由特定环路参数决定」的连续叙事；方法学（化学遗传学 + 电生理 + 群体编码）与 <code>topics/biomedicine/index.md</code> 的神经调控线互参。</p><hr>',36)])])}const m=n(e,[["render",g]]);export{h as __pageData,m as default};
